window.ScripturaLexicons.BDAG_PART_0090 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaiopragia-bdag\" data-source=\"BDAG\" data-search=\"δικαιοπραγία, ας, ἡ dikaiopragía substantivo feminino ação justa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαιοπραγία, ας, ἡ</td><td>substantivo feminino</td><td>ação justa</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaios-bdag\" data-source=\"BDAG\" data-search=\"δίκαιος, αία, ον díkaios adjetivo reto; justo; equitativo; correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δίκαιος, αία, ον</td><td>adjetivo</td><td>reto; justo; equitativo; correto</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaiosyne-bdag\" data-source=\"BDAG\" data-search=\"δικαιοσύνη, ης, ἡ dikaiosýnē substantivo feminino justiça; retidão; integridade; justificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαιοσύνη, ης, ἡ</td><td>substantivo feminino</td><td>justiça; retidão; integridade; justificação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaioo-bdag\" data-source=\"BDAG\" data-search=\"δικαιόω dikaióō verbo fazer justiça; vindicar; justificar; absolver; libertar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαιόω</td><td>verbo</td><td>fazer justiça; vindicar; justificar; absolver; libertar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaioma-bdag\" data-source=\"BDAG\" data-search=\"δικαίωμα, ατος, τό dikaíōma substantivo neutro prescrição; exigência; mandamento; ato justo; absolvição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαίωμα, ατος, τό</td><td>substantivo neutro</td><td>prescrição; exigência; mandamento; ato justo; absolvição</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaios-adv-bdag\" data-source=\"BDAG\" data-search=\"δικαίως dikaíōs advérbio justamente; equitativamente; corretamente; retamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαίως</td><td>advérbio</td><td>justamente; equitativamente; corretamente; retamente</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikaiosis-bdag\" data-source=\"BDAG\" data-search=\"δικαίωσις, εως, ἡ dikaíōsis substantivo feminino justificação; vindicação; absolvição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαίωσις, εως, ἡ</td><td>substantivo feminino</td><td>justificação; vindicação; absolvição</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dikastes-bdag\" data-source=\"BDAG\" data-search=\"δικαστής, οῦ, ὁ dikastḗs substantivo masculino juiz; magistrado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δικαστής, οῦ, ὁ</td><td>substantivo masculino</td><td>juiz; magistrado</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dike-bdag\" data-source=\"BDAG\" data-search=\"δίκη, ης, ἡ díkē substantivo feminino pena; punição; Justiça personificada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δίκη, ης, ἡ</td><td>substantivo feminino</td><td>pena; punição; Justiça personificada</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diktyon-bdag\" data-source=\"BDAG\" data-search=\"δίκτυον, ου, τό díktyon substantivo neutro rede; rede de pesca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δίκτυον, ου, τό</td><td>substantivo neutro</td><td>rede; rede de pesca</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dilogos-bdag\" data-source=\"BDAG\" data-search=\"δίλογος, ον dílogos adjetivo insincero; de fala dúplice BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δίλογος, ον</td><td>adjetivo</td><td>insincero; de fala dúplice</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dio-bdag\" data-source=\"BDAG\" data-search=\"διό dió conjunção inferencial portanto; por essa razão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διό</td><td>conjunção inferencial</td><td>portanto; por essa razão</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diognetos-bdag\" data-source=\"BDAG\" data-search=\"Διόγνητος, ου, ὁ Diógnētos nome próprio masculino Diogneto; destinatário da Epístola a Diogneto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Διόγνητος, ου, ὁ</td><td>nome próprio masculino</td><td>Diogneto; destinatário da Epístola a Diogneto</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diodeuo-bdag\" data-source=\"BDAG\" data-search=\"διοδεύω diodeúō verbo atravessar; percorrer; viajar; circular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διοδεύω</td><td>verbo</td><td>atravessar; percorrer; viajar; circular</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dioikesis-bdag\" data-source=\"BDAG\" data-search=\"διοίκησις, εως, ἡ dioíkēsis substantivo feminino administração; gestão; governo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διοίκησις, εως, ἡ</td><td>substantivo feminino</td><td>administração; gestão; governo</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dionysios-bdag\" data-source=\"BDAG\" data-search=\"Διονύσιος, ου, ὁ Dionýsios nome próprio masculino Dionísio; membro do Areópago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Διονύσιος, ου, ὁ</td><td>nome próprio masculino</td><td>Dionísio; membro do Areópago</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dioper-bdag\" data-source=\"BDAG\" data-search=\"διόπερ dióper conjunção inferencial portanto; precisamente por essa razão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διόπερ</td><td>conjunção inferencial</td><td>portanto; precisamente por essa razão</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diopetes-bdag\" data-source=\"BDAG\" data-search=\"διοπετής, ές diopetḗs adjetivo caído de Zeus; caído do céu; imagem celeste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διοπετής, ές</td><td>adjetivo</td><td>caído de Zeus; caído do céu; imagem celeste</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dioptra-bdag\" data-source=\"BDAG\" data-search=\"διόπτρα, ας, ἡ dióptra substantivo feminino instrumento óptico; dispositivo de observação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διόπτρα, ας, ἡ</td><td>substantivo feminino</td><td>instrumento óptico; dispositivo de observação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diorthoo-bdag\" data-source=\"BDAG\" data-search=\"διορθόω diorthóō verbo endireitar; dirigir pelo caminho correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διορθόω</td><td>verbo</td><td>endireitar; dirigir pelo caminho correto</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-dikaiopragia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοπραγία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaiopragía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Aristóteles e outros; escólios a Platão, 107e; PCairMasp 2, 1; 3, 6 [ambos do século VI d.C.]; TestDan 1:3; forma em -ξία em Justino.) <strong>Ação justa</strong>, 1Cl 32:3. — DELG, s.v. πράσσω.</div></section></article> <article id=\"entry-dikaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκαιος, αία, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦díkaios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δικαιοσύνη; Homero e posteriores; empréstimo no rabínico.) <strong>① Relativo à conformidade com elevados padrões de retidão: reto, justo, equitativo.</strong>\n<strong>ⓐ De seres humanos.</strong> <strong>α.</strong> Na tradição greco-romana, a pessoa δ. é aquela que observa os costumes e as normas de conduta, inclusive, especialmente, o serviço público, que tornam possível uma sociedade ordenada e civilizada (Homero, <i>Od.</i> 6, 120s.: a hospitalidade e o temor a Deus caracterizam a pessoa reta; Demóstenes 3, 21: um δίκαιος πολίτης coloca em primeiro lugar o interesse do Estado). Essa perspectiva abriu aos greco-romanos uma via para compreender as concepções judaicas e cristãs; por exemplo, a descrição de um supervisor eclesiástico (com σώφρων, ὅσιος), Tt 1:8. Tanto as sociedades politeístas quanto as monoteístas associavam estreitamente a retidão — com referência especial ao comportamento para com os seres humanos (cf. Platão, <i>Rep.</i> 4, 443; Aristóteles, <i>EN</i> 5, 1, 1129a–1130a) — à piedade, referente sobretudo às obrigações familiares e à divindade (Augusto consagrou essa perspectiva ao orgulhar-se de ter recebido uma coroa por sua δικαιοσύνη e εὐσέβεια, <i>Res Gestae</i> 34). Em consonância com a tradição do AT, os autores do NT acentuam a ligação entre a conduta reta e o senso de responsabilidade para com Deus; δ., assim como צַדִּיק, significa «conforme às leis de Deus e dos homens». Definição geral: ὁ ποιῶν τὴν δικαιοσύνην δ. ἐστιν, «aquele que pratica o que é correto é justo», 1Jo 3:7; cf. Ap 22:11. — Rm 5:7. δικαίῳ νόμος οὐ κεῖται, «a lei não se destina à pessoa reta», 1Tm 1:9. οὐκ ἔστιν δίκαιος, Rm 3:10 (cf. Ec 7:20); δ. παρὰ τῷ θεῷ, «justo diante de Deus», Rm 2:13; δ. ἐναντίον τοῦ θεοῦ (Gn 7:1; Jó 32:2), Lc 1:6. Com φοβούμενος τὸν θεόν, acerca de Cornélio, At 10:22; com εὐλαβής (Platão, <i>Pol.</i> 311ab ἤθη εὐλαβῆ κ. δίκαια, τὸ δικαιον κ. εὐλαβές), Lc 2:25; com ἀγαθός (Kaibel 648, 10; Josefo, <i>Ant.</i> 8, 248; 9, 132 ἀνὴρ ἀγ. κ. δίκ.; ver ἀγαθός 2aα), Lc 23:50; ἀθῷος (Sus 53), 1Cl 46:4; ὅσιος (En 103:9), 2Cl 15:3; ταπεινός, B 19:6 (ὡς δίκαιον καὶ ἀναμάρτητον, Justino, <i>D.</i> 47, 5). Servir a Deus com o coração puro torna a pessoa δ., 2Cl 11:1.\nDaí οἱ δίκαιοι, «os justos, os retos», em sentido especificamente israelita-cristão, Mt 13:43 (cf. Dn 12:3, Teodocião); Lc 1:17; 1Pe 3:12 (Sl 33:16); 1Cl 22:6 (Sl 33:16); 33:7; 45:3s.; 48:3 (Sl 117:20); 2Cl 6:9; 17:7; 20:3s.; B 11:7 (Sl 1:5s.); MPol 14:1; 17:1; também daqueles que apenas parecem justos (cf. Pv 21:2), Mt 23:28; Lc 18:9; 20:20; especificamente dos cristãos, Mt 10:41; At 14:2, códice D; 1Pe 4:18 (Pv 11:31); Hv 1, 4, 2. Com os apóstolos, MPol 19:2; cf. 1Cl 5:2. Especialmente dos justos do AT: πατέρες δ., 1Cl 30:7. Com profetas, Mt 13:17; 23:29 (talvez mestres: DHill, NTS 11, 1964/65, 296–302). De Abel (Dídimo, <i>Gen.</i> 181, 10), Mt 23:35 (a construção com τοῦ αἵματος merece atenção: GKilpatrick, BT 16, 1965, 119); Hb 11:4; de Enoque, 1Cl 9:3; de Ló, 2Pe 2:7s. (Noé: Justino, <i>D.</i> 20, 1; 138, 1; δίκαιοι καὶ πατριάρχαι, ibid. 67, 7); de João Batista (com ἅγιος), Mc 6:20; δ. τετελειωμένοι, «pessoas justas tornadas perfeitas» (isto é, que morreram), Hb 12:23. Em oposição a ἄδικοι (Pv 17:15; 29:27; En 99:3; 100:7), Mt 5:45; At 24:15; 1Pe 3:18; a ἁμαρτωλοί (Sl 1:5; En 104:6 e 12; PsSol 2:34), Mt 9:13; Mc 2:17; Lc 5:32; 15:7; a ἁμαρτωλοί e ἀσεβεῖς (Sl 1:5s.), 1Tm 1:9; 1Pe 4:18 (Pv 11:31); a πονηροί (Pv 11:15), Mt 13:49 (μοχθηροί, Taciano 3, 2). Com referência ao Juízo Final, aquele que passa pela prova é δ., «justo», Mt 25:37, 46. — Rm 1:17 (ver ζάω 2bβ); Gl 3:11; Hb 10:38 (todos os três, Hc 2:4; cf. Larfeld I 494); Rm 5:19. Ressurreição dos justos, Lc 14:14; oração do justo, Tg 5:16; cf. 5:6 (ver abaixo 1bβ). José, interessado em agir do modo correto: <strong>honrado, justo, bom</strong> (Josefo, <i>Ant.</i> 15, 106; Diodoro Sículo 33, 5, 6 ἀνδρὸς εὐσεβοῦς κ. δικαίου; Cônon [séculos I a.C.–I d.C.], 26 Fgm. 1, 17 Jac.; Galeno, CMG V/10, 3, p. 33, 13s. [XVIII/1, p. 247 K.] ἄνδρες δ.), Mt 1:19 (com conotação de «misericordioso»: DHill, ET 76, 1965, 133s.; ver δικαιοσύνη 3b).\n<strong>β. De coisas relacionadas aos seres humanos.</strong> ἔργα, 1Jo 3:12; αἷμα δ. (Jó 4:19; Lm 4:13 = αἷμα δικαίου, Pv 6:17, em que αἷ. δίκαιον é variante textual), «sangue de um homem reto» ou, melhor, «de um inocente», Mt 23:35 (ver abaixo 1bβ), e especialmente Mt 27:4, em que δ. é variante textual de ἀθῷον; AcPl Ha 11, 8; ψυχὴ δ., «alma reta» (cf. Pv 10:3; ver também GrBar 10:5), 2Pe 2:8; πνεῦμα δ., «espírito reto», Hm 5, 2, 7; ἐντολή (com ἁγία e ἀγαθή), Rm 7:12; κρίσις (Dt 16:18; Is 58:2; 2Mac 9:18; 3Mac 2:22; Josefo, <i>Ant.</i> 9, 4), Jo 5:30; 7:24; 8:16, variante textual; 2Ts 1:5; B 20:2; no plural, Ap 16:7; 19:2. φύσει δικαίᾳ, «por uma natureza reta», IEph 1:1 (Hdb., ad loc.; Orígenes, <i>C. Cels.</i> 5, 24, 8); ὁδὸς δ., «caminho reto» (<i>Vi. Aesopi</i> I G 85 P., sobre o «caminho certo»), 2Cl 5:7; B 12:4; plural, Ap 15:3.\n<strong>ⓑ De seres transcendentes.</strong> Em virtude de sua condição privilegiada como figuras de autoridade, associa-se a tais entidades a ideia de justiça ou equidade (para δ. com significado explicitamente «equitativo», ver Estrabão 4, 18, 7).\n<strong>α. Deus.</strong> (NRhizos, <i>Καππαδοκικά</i> 1856, p. 113: geralmente se presume que as divindades sejam justas ou equitativas, mas o atributo é especialmente afirmado em inscrição de Tiana Θεῷ δικαίῳ Μίθρᾳ. — JMordtmann, MAI 10, 1885, 11–14, registra vários exemplos de ὅσιος κ. δίκαιος como adjetivos aplicados a deuses no oeste da Ásia Menor. — δικ. sobre Ísis: PRoussel, <i>Les cultes égypt. à Delos</i> 1916, p. 276. — Frequentemente no AT; Josefo, <i>Bell.</i> 7, 323; <i>Ant.</i> 11, 55 [com ἀληθινός]; Justino, <i>A II</i> 12, 6; <i>D.</i> 23, 2.) <strong>Justo, reto</strong>, em referência ao julgamento divino de pessoas e nações: κριτὴς δ., «juiz justo» (Sl 7:12; 2Mac 12:6; PsSol 9:2; cf. descrição de Radamanto em Píndaro, <i>O.</i> 2, 69), 2Tm 4:8; δ. ἐν τοῖς κρίμασιν, 1Cl 27:1; 60:1; cf. 56:5 (Sl 140:5); πατὴρ δ., Jo 17:25; cf. Rm 3:26; 1Jo 2:29; cf. 3:7; ὁ θεὸς ὁ παντοκράτωρ δ., AcPlCor 2:12. Com ὅσιος (Sl 144:17; Dt 32:4), Ap 16:5; com πιστός, 1Jo 1:9.\n<strong>β. Jesus.</strong> Como ideal da pessoa reta, é chamado simplesmente ὁ δ., «o Justo» (HDechent, <i>D. ‘Gerechte’, Eine Bezeichnung für d. Messias</i>: StKr 100, 1928, 439–43), At 7:52; 22:14; Mt 27:19; cf. v. 24, variante textual; 1Jo 2:1; 3:7b; Lc 23:47 (sobre associações greco-romanas favoráveis à pessoa reta, especialmente em Lc 23:47, ver Danker, <i>Benefactor</i> 1982, 345s.; GKilpatrick, JTS 42, 1941, 34–36, prefere «inocente», como também Goodsp., <i>Probs.</i> 90s.; contra essa interpretação, ver RHanson, <i>Hermathena</i> 60, 1942, 74–78; RKarris, JBL 105, 1986, 65–74). Com ἅγιος, At 3:14. Sobre a questão de Tg 5:6 aplicar-se a Jesus, ver KAland, TLZ 1944, 103 e MDibelius, <i>Commentary</i> (<i>Hermeneia</i>), ad loc. (mas ver nota de Greeven nesse comentário, p. 240, n. 58: «talvez uma alusão velada e melancólica à morte de Tiago»). — Também dos anjos, Hs 6, 3, 2.\n<strong>② O neutro designa aquilo que é obrigatório à vista de certas exigências de justiça; correto, justo, equitativo</strong> (Dio Crisóstomo 67 [17], 12; Josefo, <i>Ant.</i> 15, 376; cf. Estrabão 4, 18, 7; ver Larfeld I 494). δ. παρὰ θεῷ, «é justo diante de Deus», 2Ts 1:6; δ. ἐνώπιον τοῦ θεοῦ, At 4:19; δ. καὶ ὅσιον, «é justo e santo», 1Cl 14:1; no plural, Fp 4:8; δ. ἐστιν, «é justo», Ef 6:1; seguido de infinitivo, Fp 1:7; 1Cl 21:4 (cf. Hipérides 6, 14; PSI 442, 14 [século III a.C.] οὐ δίκαιόν ἐστι οὕτως εἶναι; Sir 10:23; 2Mac 9:12; 4Mac 6:34); δ. ἡγοῦμαι, «considero justo» (Diodoro Sículo 12, 45, 1 δ. ἡγοῦντο), 2Pe 1:13; τὸ δ. (Apiano, <i>Bell. Civ.</i> 4, 97 § 409, τὸ δ. = «a causa justa»; Arriano, <i>Anab.</i> 3, 27, 5; Políbio; IMagnMai; SEG XLI, 625, 5; papiros; 2Mac 4:34; 10:12; 3Mac 2:25; EpArist; Josefo, <i>Bell.</i> 4, 340; <i>Ant.</i> 16, 158; το νῦν δ., Taciano 1, 3), «o que é justo», Lc 12:57; τὸ δ. παρέχεσθαι, «dar o que é justo», Cl 4:1; ὸ̔ ἐὰν ᾖ δ. δώσω ὑμῖν, «o que quer que seja justo vos darei», Mt 20:4 (Diodoro Sículo 5, 71, 1 τὸ δίκαιον άλλήλοις διδόναι; 8, 25, 4). Abstrato empregado por concreto (Filípica [= Demóstenes 12] 23 μετὰ τοῦ δ.; Dio Crisóstomo 52 [69], 6 ἄνευ νόμου κ. δικαίου; Élio Aristides 46, p. 302 D.): τὸ δίκαιον ὀρθὴν ὁδὸν ἔχει, «a retidão segue o caminho reto», Hm 6, 1, 2. No plural (Diodoro Sículo 15, 11, 1; 19, 85, 3; Apiano, <i>Samn.</i> 11 § 4 e outros; Luciano, <i>Dial. Mort.</i> 30, 1; Josefo, <i>Ant.</i> 19, 288; SibOr 3, 257; Justino, <i>A I</i> 68, 3 δ. ἀξιοῦν; <i>D.</i> 28, 4 φυλάσσει τὰ αἰώνια δ.), δίκαια βουλεύεσθαι, «ter pensamentos retos», Hv 1, 1, 8 (cf. λαλεῖν, Is 59:4; ἐκζητήσεται, 1Mac 7:12; κρίνειν, Ar. 15, 4; Justino, <i>A II</i> 15, 5). — B. 1180; DELG, s.v. δίκη; M-M; TW; Spicq; Sv.</div></section></article> <article id=\"entry-dikaiosyne-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaiosýnē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δίκαιος; Teógnis, Heródoto e posteriores.) De modo geral, <strong>a qualidade de ser reto</strong>. Teógnis 1, 147 define δ. como a soma de toda ἀρετή; segundo Demóstenes (20, 165), é o contrário de κακία. Uma classificação rigorosa de δ. no NT é dificultada pela frequente interação de aspectos abstratos e concretos provenientes das culturas do AT e greco-romana, nas quais o senso de equidade se combina com a consciência da responsabilidade no contexto social.\n<strong>① Qualidade, condição ou prática da responsabilidade judicial, com ênfase na imparcialidade: justiça, equidade, imparcialidade.</strong> <strong>ⓐ De seres humanos.</strong> (Tema comum em inscrições honoríficas, p.ex., IPriene 71, 14s.; 22s., a respeito de um juiz chamado Alexis; Danker, <i>Benefactor</i> 346–48; cf. Aristóteles, <i>EN</i> 5, 1, 8, 1129a τὸ μὲν δίκαιον ἄρα τὸ νόμιμον καὶ τὸ ἴσον, «a retidão consiste naquilo que é conforme à lei e equitativo»; Ath. 34:2 ἔστι δὲ δ. ἴσα ἴσοις ἀμείβειν, «retidão significa retribuir o igual com o igual»; sobre a associação de δ. ao julgamento, ver também Diógenes Laércio 3, 79; em contextos de louvor, δ. sugere autoridade que envolve responsabilidade jurídica, FX 7, 1981, 255, n. 229.) δ. κρίσεως ἀρχὴ καὶ τέλος, «a retidão é o princípio e o fim do julgamento», B 1:6. Melquisedeque como βασιλεὺς δικαιοσύνης, Hb 7:2. ἐργάζεσθαι δικαιοσύνην, «administrar justiça», Hb 11:33; κρίνειν ἐν δ., «julgar justamente» (Sl 71:2s.; 95:13; Sir 45:26; PsSol 8:24), At 17:31; cf. Mc 16:14, variante textual (manuscrito Freer, linha 5 do novo apêndice); Rm 9:28, variante textual (Is 10:22). ποιεῖν κρίμα καὶ δ., «praticar justiça e retidão», 1Cl 13:1 (Jr 9:23). καθιστάναι τοὺς ἐπισκοπούς ἐν δ., «designar supervisores com retidão», isto é, que servirão de maneira justa, 1Cl 42:5 (Is 60:17). Davi se alegra na δ. de Deus, 1Cl 18:15 (Sl 50:16; ver ἀγαλλιάω, ao final). <strong>ⓑ De figuras transcendentes.</strong> (Platão: τὴν δ. θεοῦ νόμον ὑπελάμβανεν, «considerava a justiça divina [isto é, a distribuição de recompensa ou retribuição conforme a conduta] um princípio» ou «sistema» que dissuadia da prática de crimes, Diógenes Laércio 3, 79.) Sobre um cavaleiro apocalíptico, ἐν δικαιοσύνῃ κρινεῖ, Ap 19:11.\n<strong>② Qualidade ou condição de correção jurídica com ênfase na ação redentora: justiça, retidão.</strong> A equidade associa-se especialmente a Deus (cf. <i>Paradoxogr. Vat.</i> 43 Keller αἰτεῖται παρὰ τ. θεῶν οὐδὲν ἄλλο πλὴν δικαιοσύνης) e, em nossa literatura, frequentemente ao exercício da prerrogativa executiva de conceder um benefício. Assim, a δ. de Deus pode ser o contrário da condenação, 2Co 3:9 (ver abaixo); nela Deus se revela juiz, Rm 3:5 — em contraste com a ira humana, que obscurece o julgamento —, manifestando integridade judicial, Rm 3:25 (sobre essa passagem, ver também abaixo); cf. ἐκάλεσά σε ἐν δ., B 14:7 (Is 42:6). Também acerca de uma prerrogativa equitativa conferida por Deus, 2Pe 1:1.\nNo pensamento paulino, a íntima associação entre o interesse de Deus em conservar sua reputação de justo, que recompensa o bem e retribui o mal, e, ao mesmo tempo, realizar um plano de salvação para toda a humanidade torna complexa a classificação dos usos de δικαιοσύνη. Por um lado, a δ. de Deus é ação que perdoa; por outro, é um meio de compartilhar o caráter divino com os crentes, que então manifestam justiça em sentido moral. Deus alcança esse objetivo exercendo sua prerrogativa de dispensar justiça equitativamente, sem referência a νόμος, ao tornar disponível a salvação para toda a humanidade (que compartilha o problema comum de estar sujeita à ira, pois toda ela se encontra em rebelião contra Deus, Rm 3:9–18, 23), mediante a fé na ação de Deus em Jesus Cristo. A construção genitiva δ. θεοῦ ressalta a singularidade dessa δ.: Rm 1:17; 3:21s., 25, 26 (ver também abaixo essas passagens; Reumann, ao final de 3c); 10:3; e δ. isoladamente, Rm 5:21; 9:30 (três vezes); 2Co 3:9 (oposta a κατάκρισις; cf. Dg 9:3, 5). 2Co 5:21 talvez se enquadre aqui, caso δ. seja entendida como abstrato pelo concreto, equivalente a δικαιωθέντες (mas ver abaixo). Todos esses lugares se referem à justiça concedida por Deus; cf. ἡ δωρεὰ τῆς δ., Rm 5:17; também 1Co 1:30 (de maneira semelhante, 1QS 11, 9–15; 1QH 4, 30–37). Nesse âmbito, aproxima-se muito de «salvação» (cf. Is 46:13; 51:5; ver NSnaith, <i>Distinctive Ideas of the OT</i> 1946, 207–22, especialmente 218–22; EKäsemann, ZTK 58, 1961, 367–78 [contra ele, RBultmann, JBL 83, 1964, 12–16]). Segundo alguns intérpretes, «ter fome e sede de retidão», Mt 5:6, talvez apresente (mas ver 3a abaixo) um sentido escatológico correlato («Reino de Deus», FNötscher, Biblica 31, 1950, 237–41 = <i>Vom A zum NT</i>, 1962, 226–30).\nA observância da Lei não pode produzir retidão, Rm 3:21; Gl 2:21; 3:21, porque δ. ἐκ τοῦ νόμου, «retidão baseada na Lei», Rm 10:5 (cf. 9:30s.), como ἰδία δ., «retidão própria» (produzida por si mesmo), Rm 10:3, é impossível. A δ. de Deus sem referência a νόμος deve ser apreendida pela fé, Rm 1:17; 3:22, 26; 4:3ss., 13; 9:30; 10:4, 6, 10 (cf. Hb 11:7 ἡ κατὰ πίστιν δ., «retidão baseada na fé»; ver B-D-F § 224, 1), razão pela qual a fé é «computada como justiça» (Gn 15:6; Sl 105:31; 1Mac 2:52), Rm 4:3, 5s., 9, 11, 13, 22; Gl 3:6 (cf. Hb 11:7; Tg 2:23; AMeyer, <i>D. Rätsel des Jk</i> 1930, 86ss.; 1Cl 10:6; B 13:7). De Jesus como nossa justiça, 1Co 1:30.\nComo dom e poder, Rm 5:17, 21, e por estar intimamente associada à δύναμις da ressurreição de Cristo, Fp 3:9s. (ver abaixo), essa justiça capacita os redimidos a corresponder e servir a Deus fielmente, Rm 6:13 (em jogo de palavras por oposição a ἀδικία), 16, 18ss.; cf. 1Co 1:30, de Cristo como instrumento do dom divino da δ.; 2Co 3:9. Assim, a δ. de Deus atua como δύναμις, 2Co 6:7, dentro dos cristãos, 2Co 5:21 (isto é, a maneira pela qual Deus age ao justificar ou restaurar as pessoas à relação consigo mesmo serve de modelo para as relações dos cristãos; para uma opinião diferente, ver acima), mediante o Espírito (Rm 8:9), e lhes assegura que terão vida plenamente realizada no fim da era, Rm 8:10s.; por enquanto, trata-se de esperança, ἐλπὶς δικαιοσύνης, Gl 5:5 (cf. Is 51:5); cf. ἡ ἐκ θεοῦ δ., Fp 3:9. Pol 8:1 compartilha a concepção de Paulo: Cristo como ἀρραβὼν τῆς δ. — A retidão divina como dom: τοῦ κυρίου τοῦ ἐφ’ ὑμᾶς στάξαντος τὴν δ., «do Senhor que destila a retidão sobre vós», Hv 3, 9, 1. — Tais perspectivas oferecem uma transição para os modos específicos pelos quais os redimidos expressam a retidão.\n<strong>③ Qualidade ou característica do comportamento reto: retidão, justiça.</strong> <strong>ⓐ Da retidão em geral:</strong> Mt 5:6 (cf. 6:33; alguns interpretam 5:6 em sentido escatológico, ver 2 acima; sobre o desejo de δ., cf. ἐπιθυμία τῆς δ., Hm 12, 2, 4); Mt 5:10, 20 (ver b abaixo); Hm 10, 1, 5; Dg 10:8; λόγος δικαιοσύνης, Hb 5:13; Pol 9:1 (ver também Epicteto, <i>Fgm. Stob.</i> 26: quando um homem é entusiasmado pelo λόγος nas reuniões, deve dar expressão a τὰ τῆς δικαιοσύνης λόγια). πάσχειν διὰ δ., 1Pe 3:14. ἄγγελος τῆς δ., Hm 6, 2, 1; 3; 8; 10; ῥήματα δ., Hm 8:9; 10, 1, 5; Dg 10:8; Pol 2:3; 3:1; ἐντολὴ δ., «mandamento de retidão», Pol 3:3; 9:1.\nMt 6:33, acerca da espécie de δ. que Deus exige (sobre δ. como característica exigida por Deus na perspectiva judaica, ver Bousset, <i>Rel.</i>³ 387ss.; 379ss.; 423; cf. KFahlgren, <i>Sẹdāḳā, nahestehende u. entgegengesetzte Begriffe im Alten Testament</i>, dissertação, Uppsala, 1932. — Ver Diógenes Laércio 3, 83, sobre a visão platônica de δικαιοσύνη περὶ θεούς ou δ. πρὸς τοὺς θεούς = «cumprimento dos deveres prescritos para com os deuses»; ver também a referência a 3, 79 em 1b acima). A δ. de Cristo, Dg 9:3, 5; διαλέγεσθαι περὶ δ., At 24:25. Em oposição a ἀδικία (Hipólito, <i>Ref.</i> 4, 43, 12; Dídimo, <i>Gen.</i> 20, 27), 2Cl 19:2; Dg 9:1. Como ἀρετή, Hm 1:2; Hs 6, 1, 4; 8, 10, 3. Em oposição a ἀνομία, 2Co 6:14; cf. 2Co 11:15 (ironicamente); Hb 1:9 (Sl 44:8); a ἁμαρτία, poder dominante antes de entrar em ação a δ. θεοῦ, Rm 6:16, 18–20; cf. 1Pe 2:24.\nἐργάζεσθαι δ. (Sl 14:2), «fazer o que é correto», At 10:35; «realizar a justiça», Tg 1:20 (W-S. § 30, 7g); Hv 2, 2, 7; 2, 3, 3; m 5, 1, 1; 12, 3, 1; 12, 6, 2; Hs 9, 13, 7. Também ἔργον δικαιοσύνης ἐργάζεσθαι, 1Cl 33:8; em oposição a οὐδὲν ἐργάζεσθαι τῇ δ., Hs 5, 1, 4; ποιεῖν (τὴν) δ. (2Rs 8:15; Sl 105:3; Is 56:1; 58:2; 1Mac 14:35 e outros), «fazer o que é correto», 1Jo 2:29; 3:7, 10; Ap 22:11; 2Cl 4:2; 11:7; também πράσσειν τὴν δ., 2Cl 19:3; διώκειν τὴν δ. (cf. Sir 27:8 διώκ. τὸ δίκαιον), «buscar alcançar/obter retidão», Rm 9:30; 1Tm 6:11; 2Tm 2:22; 2Cl 18:2; δ. ἀσκεῖν, Hm 8:10. ὁδὸς (τῆς) δ. (ver ὁδός 3ab), Mt 21:32; 2Pe 2:21; B 1:4; 5:4. προπορεύσεται ἔμπροσθεν σου ἡ δ., B 3:4 (Is 58:8); cf. 4:12. κατορθοῦσθαι τὰς ὁδοὺς ἐν δ., «andar retamente», Hv 2, 2, 6; τῇ δ. ζήσωμεν, «vivamos retamente», 1Pe 2:24. πύλη δ., «porta da retidão», 1Cl 48:2 (Sl 117:19), cf. v. 4; ἐν οἷς δ. κατοικεῖ (cf. Is 32:16), «nos quais habita a justiça», 2Pe 3:13. Do corpo de Cristo: δικαιοσύνης ναο͂ς, AcPlCor 2:17. παιδεία ἡ ἐν δ., «instrução na retidão», 2Tm 3:16; ἔργα τὰ ἐν δ., «obras justas», Tt 3:5; λαμπρότης ἐν δ., «alegria na retidão», 1Cl 35:2; ἐχθρὸς πάσης δ., «inimigo de toda forma de retidão», At 13:10.\nCom ὁσιότης (Sb 9:3), «santidade e retidão», como aspectos religioso e moral da conduta (cf. 1QS 1:5; 8:2; 11:9–15; 1QH 4:30s.), Lc 1:75 (λατρεύειν ἐν δ., como Js 24:14); Ef 4:24; 1Cl 48:4; com πίστις (OGI 438, 8; 1Mac 14:35; Justino, <i>D.</i> 110, 3), Pol 9:2; cf. 2Pe 1:1; com εἰρήνη (Is 39:8; 48:18) e χαρά, Rm 14:17; cf. 1Cl 3:4; Hb 7:2 (mas ver 1a acima); com ἀλήθεια (Is 45:19; 48:1), Ef 5:9; 1Cl 31:2; 62:2; Hs 9, 25, 2; com ἀγάπη, 2Cl 12:1; com ἀγαθωσύνη, Ef 5:9; com ἁγνεία, Hs 9, 16, 7; com γνῶσις κυρίου (cf. Pv 16:8), D 11:2. ὅπλα (τῆς) δ., «instrumentos ou armas da retidão», Rm 6:13; 2Co 6:7; Pol 4:1; θῶραξ τῆς δ. (Is 59:17; Sb 5:18), «couraça da retidão», Ef 6:14; τέκνα δικαιοσύνης (opostos a ὀργῆς), AcPlCor 2:19; διάκονοι δικαιοσύνης, «servos da retidão», 2Co 11:15; Pol 5:2; μισθός δ., D 5:2; B 20:2; μέρος δ., «porção da retidão» (na salvação eterna), ApPt Rainer 6; καρπὸς δικαιοσύνης (Pv 3:9; 11:30; 13:2), «fruto da retidão» (ApcSed 12:5), Fp 1:11; Hb 12:11; Tg 3:18; Hs 9, 19, 2; GJs 6:3.\nὁ τῆς δ. στέφανος, «a coroa da retidão» (com a qual os retos são adornados; cf. TestLevi 8:2; Rtzst., <i>Mysterienrel.</i>³ 258; tema comum nas inscrições honoríficas que reconhecem serviços públicos eminentes; ver índices de SIG, OGI e outros corpora epigráficos; Danker, <i>Benefactor</i> 345–47; ver também a pretensão de Augusto, s.v. δίκαιος 1aα), 2Tm 4:8; cf. ἡ τ. δικαιοσύνης δόξα, «a glória da retidão», final de Marcos no manuscrito Freer, linhas 11s. Descrita como característica que deve ser ensinada e aprendida, pois depende do conhecimento da vontade de Deus: κῆρυξ δ., «pregador da retidão», 2Pe 2:5 (cf. Ar. 15:2 τῇ δ. τοῦ κηρύγματος); διδάσκειν δ., «ensinar a retidão» (acerca de Paulo), 1Cl 5:7; μέρος τι ἐκ τῆς δ., «alguma porção da retidão», Hv 3, 1, 6; cf. 3, 6, 4; δ. μεγάλην ἐργάζεσθαι, m 8:2. — ἐλέγχειν περὶ δικαιοσύνης, «convencer quanto à retidão» (acerca de Jesus), Jo 16:8, 10 (ver WHatch, HTR 14, 1921, 103–5; HWindisch, em <i>Jülicher Festschr.</i> 1927, 119s.; HTribble, <i>Rev. and Expos.</i> 32, 1937, 269–80; BLindars, <i>BRigaux Festschr.</i> 1970, 275–85).\n<strong>ⓑ De ação específica:</strong> justiça no sentido de cumprir as expectativas divinas que não estão expressas especificamente em ordenanças (Orígenes, <i>C. Cels.</i> 7, 18, 39; Dídimo, <i>Gen.</i> 188, 27: οἱ κατὰ δ. ζῶντες), Mt 3:15 = ISm 1:1; de um tipo superior, Mt 5:20 (ver JMoffatt, ET 13, 1902, 201–6; OOlevieri, Biblica 5, 1924, 201ss.; Betz, <i>SM</i> 190s.); não para conquistar aplausos, Mt 6:1; para agradar aos de fora tanto quanto a si mesmo, 2Cl 13:1. Com a restrição característica de sentido «misericórdia, caridade» (cf. Tb 12:9), acerca de Deus, cuja solicitude pelos pobres, 2Co 9:9 (Sl 111:9), serve de exemplo aos destinatários da carta, v. 10; participar dessa atividade pertence, segundo Mt 6:1s. (cf. δίκαιος em Mt 1:19: José reúne justiça e misericórdia), à prática da piedade (sobre a evolução semântica do termo nessa direção, ver Bousset, <i>Rel.</i>³ 380). No plural (B-D-F § 142; W-S. § 27, 4d; Rob. 408), δικαιοσύναι, «atos justos» (Ez 3:20; 33:13; Dn 9:18), 2Cl 6:9. δικαιοσύναι, «atos justos» (Ez 3:20; 33:13; Dn 9:18; TestAbr A 12, p. 91, 12 [Stone, p. 30]), 2Cl 6:9. ἀρετὴ δικαιοσύνης, Hm 1:2; Hs 6, 1, 4; cf. 8, 10, 3.\n<strong>ⓒ Retidão determinada por padrões divinos ou legais:</strong> δ. θεοῦ, «retidão conforme ao padrão divino», Tg 1:20 (W-S. § 30, 7g). — Rm 10:5; Gl 2:21; 3:21; Fp 3:6; 3:9.\n— ASchmitt, «Δικαιοσύνη θεοῦ»: <i>JGeffcken Festschr.</i> 1931, 111–31; FHellegers, <i>D. Gerechtigkeit Gottes im Rö.</i>, diss. Tübingen, 1939; AOepke, TLZ 78, 1953, 257–64. — Dodd 42–59; ADescamps, <i>Studia Hellenistica</i>, 1948, 69–92. — Ver também JRopes, «Righteousness in the OT and in St. Paul»: JBL 22, 1903, 211ss.; JGerretsen, <i>Rechtvaardigmaking bij Pls</i> 1905; GottfrKittel, StKr 80, 1907, 217–33; ETobac, <i>Le problème de la Justification dans S. Paul</i> 1908; EDobschütz, «Über d. paul. Rechtfertigungslehre»: StKr 85, 1912, 38–87; GWetter, <i>D. Vergeltungsged. b. Pls</i> 1912, 161ss.; BWestcott, <i>St. Paul and Justification</i> 1913; WMacholz, StKr 88, 1915, 29ss.; EBurton, <i>ICC, Gal.</i> 1921, 460–74; WMichaelis, «Rechtf. aus Glauben b. Pls»: <i>Deissmann Festschr.</i> 1927, 116–38; ELohmeyer, <i>Grundlagen d. paul. Theologie</i> 1929, 52ss.; HBraun, <i>Gerichtsged. u. Rechtfertigungslehre b. Pls</i> 1930; OZänker, «Δικαιοσύνη θεοῦ b. Pls»: ZST 9, 1932, 398–420; FFilson, <i>St. P.’s Conception of Recompense</i> 1931; WGrundmann, ZNW 32, 1933, 52–65; H-DWendland, <i>D. Mitte der paul. Botschaft</i> 1935; RGyllenberg, «D. paul. Rechtfertigungslehre u. das AT»: <i>Studia Theologica</i> (Riga) I, 1935, 35–52; HJager, <i>Rechtvaardiging en zekerheid des geloofs</i> (Rm 1:16s.; 3:21–5:11), 1939; HHofer, <i>D. Rechtfertigungsverk. des Pls nach neuerer Forschg.</i> 1940; VTaylor, <i>Forgiveness and Reconciliation</i> 1941; RBultmann, <i>Theologie des NT</i> 1948, 266–80, trad. inglesa KGrobel 1951, I 270–85; SSchulz, ZTK 56, 1959, 155–85 (Qumran e Paulo); CMüller, FRL 86, 1964 (Rm 9–11); JBecker, <i>Das Heil Gottes</i> 1964; PStuhlmacher, <i>Gerechtigkeit Gottes b. Paulus</i> 1965; JReumann, Int 20, 1966, 432–52 (Rm 3:21–31); HBraun, <i>Qumran</i> II, 1966, 165–80; JZiesler, <i>The Mng. of Righteousness in Paul</i> 1972; ESanders, <i>Paul and Palestinian Judaism</i> 1977 (ver índice, p. 625; apêndice de MBrauch, p. 523–42, revisão das discussões na Alemanha); SWilliams, JBL 99, 1980, 241–90. — CPerella, «De justificatione sec. Hb»: Biblica 14, 1933, 1–21; 150–69. Ver também bibliografia sobre πίστις e ἁμαρτία. — Sobre toda a palavra, ver RAC X, 233–360; AKöberle, <i>Rechtfertigung u. Heiligung</i> 1930; EDNT I, 325–30. — DELG, s.v. δίκη; M-M; EDNT; TW; Sv.</div></section></article> <article id=\"entry-dikaioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Futuro δικαιώσω; primeiro aoristo ἐδικαίωσα. Passivo: primeiro futuro δικαιωθήσομαι; primeiro aoristo ἐδικαιώθην; subjuntivo δικαιωθῶ; particípio δικαιωθείς; perfeito δεδικαίωμαι, Rm 6:7; 1Co 4:4; particípio δεδικαιωμένος, Lc 18:14 (Sófocles, Heródoto; Aristóteles, <i>EN</i> 1136a; outros; papiros, LXX; En 102:10; TestAbr A 13, p. 93, 14 [Stone, p. 34]; Test12Patr; ApcSed 14:8, p. 136, 15 Ja.; Josefo, <i>Ant.</i> 17, 206; Justino; Atenágoras, <i>R.</i> 53, 1; 65, 14). <strong>Praticar δικαιοσύνη.</strong>\n<strong>① Assumir uma causa jurídica, mostrar justiça, fazer justiça, defender uma causa.</strong> Com τινά (Políbio 3, 31, 9 ὑμᾶς δὲ αὐτοὺς … δικαιώσεσθε, «vós (considerareis necessário) defender vossa própria causa», isto é, «vos julgareis a vós mesmos»; Cássio Dio 48, 46: «Antônio não tomava o partido de César» nessa questão; 2Rs 15:4; Sl 81:3); δικαιῶσαι δίκαιον, «defender a causa de uma pessoa reta», 1Cl 16:12 (Is 53:11); τινί χήρᾳ (variante textual χήραν), 1Cl 8:4 (Is 1:17, «defender a causa da viúva»).\n<strong>② Proferir um veredito favorável; vindicar.</strong> <strong>ⓐ Como atividade humana: justificar, vindicar, tratar como justo</strong> (Apiano, <i>Liby.</i> 17 § 70; Gn 44:16; Sir 10:29; 13:22; 23:11 e outros); θέλων δ. ἑαυτόν, «querendo justificar-se», Lc 10:29; δ. ἑαυτὸν ἐνώπιόν τινος, «justificar-se perante alguém», isto é, «vós procurais apresentar uma boa defesa de vós mesmos perante o público», Lc 16:15 (δ. ἐαυτόν, como En 102:10; mas ver JJeremias, ZNW 38, 1939, 117s. [contra ele SAalen, NTS 13, 1967, 1ss.]). ὁ δικαιούμενός μοι, «aquele que se vindica perante mim (ou contra mim)», B 6:1 (cf. Is 50:8). τελῶναι ἐδικαίωσαν τὸν θεόν βαπτισθέντες, «os publicanos reconheceram a retidão de Deus e foram batizados», isto é, decidindo a favor de Deus, admitiram que estavam errados e tomaram uma nova direção (em oposição a τὴν βουλὴν τ. θεοῦ ἀθετεῖν), Lc 7:29 (cf. PsSol 2:15; 3:5; 8:7, 23; 9:2).\n<strong>ⓑ Da experiência ou atividade de figuras transcendentes, especialmente em relação aos seres humanos.</strong>\n<strong>α. Da sabedoria:</strong> ἐδικαιώθη ἀπὸ τῶν τέκνων αὐτῆς, «é vindicada por seus filhos» (sobre δικ. ἀπό, cf. Is 45:25; ver também Apiano, <i>Basil.</i> 8, δικαιόω = «considerar algo justo ou correto»), Lc 7:35; também ἀπὸ τῶν ἔργων αὐτῆς, Mt 11:19 (variante textual τέκνων). Sobre esse dito, ver DVölter, NThT 8, 1919, 22–42; JBover, Biblica 6, 1925, 323–25; 463–65; M-JLagrange, ibid., 461–63. De um anjo, Hm 5, 1, 7.\n<strong>β. De Deus: ser considerado justo, ficar livre de acusações</strong> (cf. TestAbr A 13, p. 93, 14 [Stone, p. 34], «ser vindicado» em uma prova de fogo), Mt 12:37 (em oposição a καταδικάζειν); δεδικαιωμένος, Lc 18:14; GJs 5:1; δεδικαιωμένη (Salomé), GJs 20:4 (não em papiros); At 13:39 (mas ver 3 abaixo); Ap 22:11, variante textual; Dg 5:14.\nPaulo, que influenciou autores posteriores (cf. Irineu 3, 18, 7 [Harv. II 102, 2s.]), emprega a palavra quase exclusivamente com referência ao julgamento de Deus. Como veredito afirmativo, Rm 2:13. Especialmente de pessoas, δικαιοῦσθαι, «ser absolvido, ser declarado e tratado como justo» e, desse modo, tornar-se δίκαιος, receber o dom divino da δικαιοσύνη mediante a fé em Cristo Jesus, sem νόμος como base de avaliação (MSeifrid, <i>Justification by Faith—The Origin and Development of a Central Pauline Theme</i> 1992), Rm 3:20 (Sl 142:2), 24, 28; 4:2; 5:1, 9; 1Co 4:4; Gl 2:16s. (Sl 142:2); 3:11, 24; 5:4; Tt 3:7; Fp 3:12, variante textual; B 4:10; 15:7; IPhld 8:2; Dg 9:4; com ἁγιάζεσθαι, Hv 3, 9, 1. οὐ παρὰ τοῦτο δεδικαίωμαι, «não sou justificado por isso» (conforme 1Co 4:4), IRo 5:1; ἵνα δικαιωθῇ σου ἡ σάρξ, «para que tua carne (como parte pecaminosa) seja absolvida», Hs 5, 7, 1; δ. ἔργοις, «pelas obras», isto é, «com base no que se faz», 1Cl 30:3; cf. Tg 2:21, 24s. (ver ἔργον 1a e πίστις 2dδ); δι’ ἐαυτῶν δ., «por si próprios», isto é, «como resultado das próprias realizações», 1Cl 32:4 (cf. κατὰ νόμον, Hipólito, <i>Ref.</i> 7, 34, 1).\nComo Paulo entende a ação justificadora de Deus em estreita conexão com o poder da ressurreição de Cristo, por vezes não há distinção clara entre a ação justificadora da absolvição e o dom da nova vida mediante o Espírito Santo, enquanto atividade divina que promove a retidão nos crentes. As passagens dessa natureza incluem Rm 3:26, 30; 4:5 (sobre δικαιοῦν τὸν ἀσεβῆ, cf. a advertência contra aceitar δῶρα para conseguir absolvição, Êx 23:7 e Is 5:23; δικαιούμενοι δωρεάν, Rm 3:24, por conseguinte, torna-se ainda mais expressivo); 8:30, 33 (Is 50:8); Gl 3:8; Dg 9:5. Para a opinião (sustentada desde Crisóstomo) de que δ. nessas e em outras passagens significa «tornar reto», ver Goodsp., <i>Probs.</i> 143–46; JBL 73, 1954, 86–91.\n<strong>③ Fazer com que alguém seja libertado de reivindicações pessoais ou institucionais que já não devem ser consideradas pertinentes ou válidas; libertar, purificar.</strong> (Forma ativa em Sl 72:13.) Em nossa literatura, passivo δικαιοῦμαι, «ser libertado, tornado puro», com ἀπό, «de» (Sir 26:29; TestSim 6:1, ambos δικ. ἀπὸ [τῆς] ἁμαρτίας); ἀπὸ πάντων ὧν οὐκ ἠδυνήθητε ἐν νόμω Μωϋσέως δικαιωθῆναι, «de tudo aquilo de que não pudestes ser libertados pela lei de Moisés», At 13:38; cf. v. 39. ὁ ἀποθανὼν δεδικαίωται ἀπὸ τ. ἁμαρτίας, «aquele que morreu está liberto do pecado», Rm 6:7 (ver KKuhn, ZNW 30, 1931, 305–10; EKlaar, ibid. 59, 1968, 131–34). No contexto de 1Co 6:11, ἐδικαιώθητε significa «fostes tornados puros». — Na linguagem das religiões de mistério (Rtzst., <i>Mysterienrel.</i>³ 258ss.), δικαιοῦσθαι refere-se a uma transformação interior radical experimentada pelo iniciado (<i>Herm. Wr.</i> 13, 9 χωρὶς γὰρ κρίσεως ἰδὲ πῶς τὴν ἀδικίαν ἐξήλασεν. ἐδικαιώθημεν, ὦ τέκνον, ἀδικίας ἀπούσης) e se aproxima do sentido «ser deificado». Alguns se inclinam a encontrar uso semelhante em 1Tm 3:16; mas ver 4.\n<strong>④ Demonstrar que alguém é moralmente correto; provar que tem razão.</strong> No passivo, de Deus, «é demonstrado que é justo», Rm 3:4; 1Cl 18:4 (ambos, Sl 50:6). De Cristo, 1Tm 3:16. — Sobre bibliografia, ver δικαιοσύνη 3c. — HRosman, «Iustificare (δικαιοῦν) est verbum causativum»: <i>Verbum Domini</i> 21, 1941, 144–47; NWatson, «Δικ. in the LXX»: JBL 79, 1960, 255–66; CCosgrove, JBL 106, 1987, 653–70. — DELG, s.v. δίκη; M-M; EDNT; TW; Spicq.</div></section></article> <article id=\"entry-dikaioma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίωμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaíōma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Tucídides e posteriores; inscrições, papiros, LXX; En 104:9; ParJer 6:23; Justino, <i>D.</i> 46, 2.) <strong>① Prescrição referente a uma ação justa ou correta; regulamento, exigência, mandamento</strong> (assim, sobretudo na LXX; Fílon, <i>Det. Pot. Ins.</i> 68; Josefo, <i>Bell.</i> 7, 110; <i>Ant.</i> 17, 108; Cássio Dio 36, 23, acerca das leis; POxy 1119, 15 τῶν ἐξαιρέτων τῆς ἡμετέρας πατρίδος δικαιωμάτων). Com ἐντολαί e κρίματα (como Nm 36:13; Dt 4:40; cf. 6:1; 7:11 e outros; cf. Teófilo de Antioquia 3, 11 [p. 226, 29]), Lc 1:6; com προστάγματα (como Gn 26:5), 1Cl 2:8; 35:7 (Sl 49:16); τὰ δεδομένα δ., «os mandamentos que foram dados», 1Cl 58:2 (δικ. διδόναι: Josefo, <i>C. Ap.</i> 2, 37); δ. τοῦ νόμου, «as exigências da Lei», Rm 2:26; 8:4. Especialmente das exigências divinas: δ. τοῦ θεοῦ, Rm 1:32; B 4:11; 10:2 (cf. Dt 4:1); [δ.] κυρίου, Hm 12, 6, 4. ἐκζητεῖν τὰ δ. κυρίου, «procurar as exigências do Senhor», B 2:1; μανθάνειν, B 21:1; γνῶσις τῶν δ., B 21:5. λαλεῖν δ. κυρίου, «falar da lei do Senhor», B 10:11; σοφία τῶν δ., «a sabedoria revelada em suas ordenanças», B 16:9; δ. λατρείας, «prescrições para o culto», Hb 9:1; δ. σαρκός, «prescrições relativas ao corpo», v. 10. <strong>② Ação que corresponde às expectativas do justo ou correto; ato justo</strong> (Aristóteles, <i>EN</i> 1135a, 12s.; <i>Rhet.</i> 1359a, 25; 1373b, 1; 3Rs 3:28; Br 2:19), δι’ ἑνὸς δικαιώματος, «por um só ato justo» (em oposição a παράπτωμα), Rm 5:18. — B 1:2 (cf. Wengst, <i>Barnabasbrief</i> 196, n. 4); Ap 15:4 (aqui, talvez, «sentença condenatória» [cf. Platão, <i>Leg.</i> 9, 864e; inscrição da Ásia Menor: LBW 41, 2 [κατὰ] τὸ δι[καί]ωμα τὸ κυρω[θέν], «segundo a sentença que adquiriu validade»]; interpretação diferente em Wengst, citado acima); 19:8. <strong>③ Ato de absolver alguém de uma infração</strong>, Rm 5:16 (em oposição a κατάκριμα); a palavra foi provavelmente escolhida por causa das outras terminadas em -μα e equivale, quanto ao sentido, a δικαίωσις (sobre a possibilidade linguística, ver Kühner–Bl. II, 272 e Schwyzer I, 491: formas em -μα que exprimem o resultado de uma ação. — Em En 104:9, δικαίωμα pode representar δικαιοσύνη [cf. Ez 18:21 e variante textual], mas o texto parece corrompido). — DELG, s.v. δίκη; M-M; TW; Spicq.</div></section></article> <article id=\"entry-dikaios-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaíōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Advérbio de δίκαιος (Homero e posteriores). <strong>① Relativo ao que é justo ou correto no sentido jurídico; justamente, de maneira reta.</strong> <strong>ⓐ</strong> Sobre a apreciação de uma causa por um juiz: «(julgar) retamente, equitativamente» (IPriene 63, 20, e frequentemente nas inscrições; Diodoro Sículo 15, 11, 2 δ. κρίνειν; Sir 35:18, variante textual), 1Pe 2:23; B 19:11; D 4:3. Em sentido sarcástico, GPt 3:7. <strong>ⓑ</strong> Sobre o tratamento que alguém merece em razão de sua conduta: «retamente, justamente, com (toda) justiça» (Xenofonte, <i>Symp.</i> 4, 60; Luciano, <i>Dial. Mort.</i> 30, 1 δ. κολασθήσομαι; Justino, <i>A I</i> 43, 8 δ. κολάσεως ἐτύγχανεν; Taciano 7:1); πάσχειν (Sb 19:13; TestSim 4:3; Justino, <i>D.</i> 110, 6), Hs 6, 3, 6; λέγειν, Hs 1:4; ἀπολέσθαι, B 5:4; καὶ ἡμεῖς μὲν δ., «e nós, de fato, fomos condenados justamente», Lc 23:41. Em oposição a οὐ δ., «de modo inteiramente injusto», 1Cl 44:3 (Justino, <i>D.</i> 107, 3). <strong>② Relativo à qualidade do caráter, do pensamento ou do comportamento; corretamente, justamente, retamente.</strong> Com ὁσίως e ἀμέμπτως, 1Ts 2:10; com ὁσίως, PtK 2, p. 15, 2 (Platão, <i>Rep.</i> 1, 331a ὁσίως κ. δικαίως; IPriene 46, 12 [século I a.C.]; 60, 8s. [século II a.C.]; UPZ 144, 13 [164 a.C.] τοῖς θεοῖς, πρὸς οὓς ὁσίως … καὶ δικαίως πολιτευσάμενος; En 106:18 δ. κ. ὁσίως; Josefo, <i>Ant.</i> 6, 87; cf. Ar. 15, 10); ἀναστρέφεσθαι, «comportar-se», 2Cl 5:6; com σωφρόνως e εὐσεβῶς, ζῆν, «viver», Tt 2:12 (Heráclides, <i>Pol.</i> 39 δ. κ. σωφρόνως βιοῦσι); cf. 1Cl 51:2; 62:1. ἀγαπᾶν, «amar corretamente», IEph 15:3; νοεῖν, «compreender corretamente», B 10:12; ἐκνήφειν, «estar sóbrio, como convém», 1Co 15:34; δ. ἀναμένειν τινά, «esperar alguém com retidão», IMagnMai 9, 3; δ. νοεῖν, «compreender corretamente», B 10:12. — M-M, s.v. δίκαιος.</div></section></article> <article id=\"entry-dikaiosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίωσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikaíōsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><strong>Justificação, vindicação, absolvição</strong> (assim em Tucídides e outros; Lv 24:22 e Símaco, Sl 34:23; PsSol 3:3), tanto como processo quanto como resultado: διὰ τὴν δ., Rm 4:25 (ver DSharp, ET 39, 1928, 87–90); εἰς δ. ζωῆς, «absolvição que traz vida», Rm 5:18. — DELG, s.v. δίκη; TW; Spicq.</div></section></article> <article id=\"entry-dikastes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dikastḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ésquilo, Heródoto e outros; inscrições, papiros, LXX, Fílon; Josefo, <i>Bell.</i> 1, 630 [Deus]; <i>Ant.</i> 7, 229 e outros; <i>C. Ap.</i> 1, 157 [δ. como principal administrador em Tiro].) <strong>Aquele que preside a processos e decide causas em tribunal; juiz.</strong> Com ἄρχων, At 7:27, 35; 1Cl 4:10 (os três, Êx 2:14); Lc 12:14, variante textual (Diodoro Sículo 4, 33, 4 δ. = «árbitro»). — DELG, s.v. δίκη; M-M; TW; Spicq.</div></section></article> <article id=\"entry-dike-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦díkē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e posteriores; inscrições, papiros, LXX; TestAbr A 2, p. 78, 18 [Stone, p. 4], δίκην, «como, à semelhança de»; TestSol 1:9 e ApcSed 3:1, «queixa» ou «acusação»; Fílon, Josefo, Justino, Atenágoras [este último também δίκην, «como»]; empréstimo no rabínico. Originalmente, «direção, caminho»; daí o acusativo adverbial δίκην, «à maneira de, como», com genitivo; em Homero, «aquilo que é correto», sobretudo segundo o costume ou uso.) <strong>① Punição imposta como sanção jurídica; castigo, pena.</strong> (Pré-socráticos, tragediógrafos e posteriores; papiros, p.ex., UPZ 1, 13 [século IV a.C.]; PFay 21, 24 [século II d.C.]; LXX.) δίκην τίνειν (tragediógrafos; Platão; Epicteto 3, 24, 4; 3, 26, 20; Plutarco, <i>Mor.</i> 553f; 559d; 561b; 592e; Eliano, <i>VH</i> 9, 8; Fílon, <i>Spec. Leg.</i> 3, 175; <i>Mos.</i> 1, 245; Justino, <i>A I</i> 17, 4; Atenágoras, <i>R.</i> 74, 2), «pagar a pena, sofrer punição, ser punido», com τι, «por alguma coisa» ou «com alguma coisa», 2Ts 1:9; Hm 2:5; Hs 9, 19, 3. Também δ. διδόναι (frequentemente nos tragediógrafos e posteriores; Josefo, <i>C. Ap.</i> 2, 143; <i>Vi.</i> 343; Justino, <i>D.</i> 1:5), D 1:5 (δ. διδόναι acerca do castigo divino também em Diodoro Sículo 16, 31, 4; mas ver RKraft, <i>The Didache and Barnabas</i> 1965, p. 141: «ser chamado a prestar contas»); e δ. ὑπέχειν (não raramente desde Sófocles, <i>Oed. Rex</i> 552; também Diógenes Laércio 3, 79; Josefo, <i>Ant.</i> 14, 45; 168), Jd 7; δ. αἰτεῖσθαι κατά τινος, At 25:15, variante textual. <strong>② Justiça personificada como divindade</strong>, At 28:4 (Sófocles, <i>Ant.</i> 538 ἀλλ’ οὐκ ἐάσαι τοῦτο γ’ ἡ Δίκη σ’, ἐπεὶ κτλ.; Élio Aristides 52, p. 606 D.; Arriano, <i>Anab.</i> 4, 9, 7, Δίκη como πάρεδρος de Zeus; Píndaro, <i>O.</i> 7, 17 e outros; Platão, <i>Leg.</i> 716a; Plotino V 8, 4, 40ss.; Damáscio, <i>Vi. Isid.</i> 138; Procópio, <i>Ep.</i> 17; 149; <i>Herm. Wr.</i> p. 420, 1 Sc.; 4Mac; Fílon; Josefo; Warnecke, <i>Romfahrt</i> 118s.). — RHirzel, <i>Themis, Dike u. Verwandtes</i> 1907; WJaeger, <i>Paideia</i> 1934, 144ss. (ver trad. inglesa, 1939, vol. 1, 68); DLoenen, <i>Dike</i> 1948; <i>Kl. Pauly</i> II, 24–26. — B. 1358; DELG; LfgrE, s.v. (bibliografia); DDD 476–80; M-M; TW; Spicq; Sv.; ver δικάζω.</div></section></article> <article id=\"entry-diktyon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκτυον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦díktyon⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e outros; PTebt 701, 88; Pseudo-Xenofonte, <i>Cyn.</i> 2, 5; Epicteto 2, 1, 8; LXX; TestAbr A 8, p. 86, 3 [Stone, p. 20]; TestDan 2:4; Josefo, <i>Ant.</i> 9, 92.) Termo genérico para <strong>rede</strong>, mas no NT somente <strong>rede de pesca</strong> (desde <i>Od.</i> 22, 386; também Diodoro Sículo 5, 76, 4; Pausânias 2, 30, 3; Luciano, <i>Herm.</i> 65; Alcífron 1, 14 e outros; ver ἀμφιβάλλω), Mt 4:20s.; Mc 1:18s.; Lc 5:2, 4ss.; Jo 21:6, 8, 11 (ἕλκειν τὸ δίκτ.: Teócrito, <i>Idyll.</i> 1, 40; <i>Vi. Aesopi</i> G 26); também para captura de aves (antigo inglês <i>fowler’s net</i>, «rede de caçador de aves»), Pv 1:17. — B. 5:4; DELG; M-M.</div></section></article> <article id=\"entry-dilogos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίλογος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dílogos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Pólux 2, 118, porém ali no sentido de «repetitivo». Semelhantemente, Diodoro Sículo 20, 37, 1, διλογεῖν τι = «dizer algo duas vezes»; cf. Nägeli 52.) <strong>Insincero, de fala dúplice</strong> (cf. o inglês <i>double-talking</i>; nos Estados Unidos, <i>double-tongued</i> pode comunicar significado diferente), 1Tm 3:8. — Pol 5:2. — B. 5:4; M-M.</div></section></article> <article id=\"entry-dio-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dió⟧</span><span class=\"separator\">·</span><span>conjunção inferencial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Conjunção inferencial (δι’ ὅ; ver B-D-F § 451, 5; Heráclito, Tucídides e posteriores): <strong>portanto, por essa razão</strong>, Mt 27:8; Mc 5:33, variante textual; Lc 7:7; At 15:19; 20:31; 25:26; 26:3; 27:25, 34; Rm 1:24; 2:1; 13:5 (RBultmann, TLZ 72, 1947, 200, eliminaria os dois últimos versículos como glosas); Hb 3:7, 10; B 4:9; 1Cl 7:2; 9:1; AcPlCor 1:16 e outros. διὸ καί (B-D-F § 442, 12; 451, 5), <strong>«por isso também»</strong>, indicando que a inferência é evidente por si (Josefo, <i>Ant.</i> 19, 294), Lc 1:35; At 10:29; 24:26; Rm 4:22; 15:22; 2Co 1:20; 5:9; Fp 2:9; AcPlCor 2:8 e outros. P⁷² lê δι’ οὗ, com referência a Cristo, em 2Pe 1:12. — EMolland, «Διο»: <i>Serta Rudbergiana</i> 1931, 43–52; ver διότι 2. — M-M.</div></section></article> <article id=\"entry-diognetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Διόγνητος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Diógnētos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Nome encontrado frequentemente; Demóstenes; Políbio; Marco Aurélio 1, 6; inscrições, papiros.) <strong>Diogneto</strong>, destinatário da <i>Epístola a Diogneto</i>, Dg 1.</div></section></article> <article id=\"entry-diodeuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοδεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diodeúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Imperfeito διώδευον; primeiro aoristo διώδευσα; passivo, terceira pessoa do singular διωδεύθη, Sb 5:11 (Aristóteles e outros; inscrições, papiros, LXX; TestZeb 4:6, variante textual; JosAs 11:1, códice A e Pal. 364; ApcMos 19; Josefo; SibOr). <strong>① Ir ou viajar através de; percorrer, atravessar</strong> (Luciano, <i>Dial. Mort.</i> 27, 2; OGI 613, 3; 665, 22; SEG XXVI, 1392, 40s.; papiros, p.ex. PAmh 36, 131; PTebt 736, 12), com τόπον τινά (cf. Sb 5:7; 11:2), At 17:1. <strong>② Andar de um lugar para outro, circular</strong>, intransitivo (IKNikaia I, 1, 7; PAmh II, 36, 13 [século II a.C.]; Josefo, <i>Bell.</i> 2, 340; Jr 2:6; 1Mac 12:32, διώδ. ἐν πάσῃ τῆ χώρᾳ; SibOr 3, 250); κατὰ πόλιν και κώμην, «de uma cidade e aldeia para outra», Lc 8:1. — Anz 344; <i>New Docs</i> 4, n. 48; DELG, s.v. ὁδό; M-M.</div></section></article> <article id=\"entry-dioikesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίκησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dioíkēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><strong>Administração, gestão</strong> (Xenofonte e posteriores; OGI 11, 24; 458, 65; papiros; Tb 1:21; Josefo, <i>Bell.</i> 1, 669; <i>Ant.</i> 15, 68; 355, δ. Καίσαρος; Justino, <i>A II</i> 8), de uma entidade política; acerca do governo de Deus sobre o mundo (Epicteto 3, 5, 8; 10; 4, 1, 100 e outros; Fílon, <i>Spec. Leg.</i> 4, 187; cf. <i>Herm. Wr.</i> 10, 23; Ar. [Milne 76, 50]; Justino; Atenágoras), τῇ δ. αὐτοῦ, «sob sua direção», 1Cl 20:1. — Dg 7:2. — DELG, s.v. οἶκο, p. 782; Sv.</div></section></article> <article id=\"entry-dionysios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Διονύσιος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Dionýsios⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Nome muito frequente.) <strong>Dionísio</strong>, nome de um ateniense (ver Josefo, <i>Ant.</i> 14, 149–52), membro do Areópago, convertido por Paulo, At 17:34. — DELG, s.v. Διόνυσο; M-M.</div></section></article> <article id=\"entry-dioper-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόπερ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dióper⟧</span><span class=\"separator\">·</span><span>conjunção inferencial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Conjunção inferencial (δι’ ὅπερ; Epicarmo 85a, 5 [CGFP]; Demócrito; Tucídides e outros; Diodoro Sículo 4, 33, 6; inscrições, papiros, LXX; Josefo, <i>Ant.</i> 16, 118; Taciano; Atenágoras): <strong>portanto, precisamente por essa razão</strong>, 1Co 8:13; 10:14; 14:13, variante textual. — M-M.</div></section></article> <article id=\"entry-diopetes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοπετής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diopetḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Literalmente, <strong>«caído de Zeus» ou «do céu»</strong>. Originalmente, relativo a meteoritos considerados objetos de culto vindos do céu (acerca de imagens de divindades: Eurípides, <i>Iph. T.</i> 86–88; 977; 1384s., Ártemis; Dionísio de Halicarnasso 2, 66, Atena; Apiano, <i>Mithrid.</i> 53 § 213, Atena; Herodiano 5, 3, 5, acerca de uma pedra muito grande que representava o deus solar Elagábalo; cf. Lívio, <i>Hist.</i> 29, 11, 14, imagem da «Magna Mater» levada de Pessinunte a Roma em 204 a.C.). Em nossa literatura, apenas como substantivo neutro τὸ διοπετές, <strong>a imagem (de Ártemis) caída do céu em Éfeso</strong>, At 19:35 (B-D-F § 241, 7). — EvDobschütz, <i>Christusbilder</i>: TU 18, 1899, 11ss.; 41; acerca do culto dos meteoritos: ACook, <i>Zeus</i> III, 1940, XII, 881–942; CHemer, <i>The Letters to the Seven Churches of Asia in Their Local Setting</i> 1986, 227, n. 39. — DELG, s.v. πέτομαι; M-M.</div></section></article> <article id=\"entry-dioptra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόπτρα, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dióptra⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Formado à semelhança de ἀντόπτρα; ver HSchoene, <i>Hermes</i> 38, 1903, 281.) <strong>Instrumento óptico</strong> (Euclides, Políbio e outros); Pápias (3:2) afirma que os olhos de Judas estavam tão inchados que um médico sequer conseguia examiná-los com o auxílio de uma δ., talvez concebida para ajudar a separar as pálpebras (cf. Aécio 16, 89; Paulo de Egina, <i>med.</i> CMG 6, 73). — DELG, s.v. ὄπωπα.</div></section></article> <article id=\"entry-diorthoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορθόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diorthóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Primeiro aoristo διώρθωσα, LXX; médio διωρθωσάμην. Passivo: primeiro futuro διορθωθήσομαι, LXX; aoristo διωρθώθην (ver os dois verbetes seguintes; Píndaro e outros; ISardGauthier 1, 2 e outros; PPetr III, 53k, 4 e outros; LXX; Josefo, <i>Ant.</i> 2, 46 e outros). <strong>Colocar no caminho correto</strong>; ἐπὶ τὸ ἀγαθὸν δ., «conduzir ao que é bom», 1Cl 21:6. — DELG, s.v. ὀρθό.</div></section></article>"};
